 const r=await tools.mcp__chemworld_lab__step({expected_step:s,action:a});
 const t=(r.content||[]).find(c=>c.type==="text")?.text; const j=JSON.parse(t); outs.push({s,ok:j.ok,obs:j.observation,proc:j.processed_estimate,score:j.leaderboard_score,nextstep:j.next_state?.step,ended:j.experiment_ended});
}
